import 'dart:math' as math;
import 'package:flutter/material.dart';
import '../../core/utils/currency_utils.dart';
import '../../data/models/expense.dart';
class WeeklyBarChart extends StatefulWidget{const WeeklyBarChart({super.key,required this.data});final List<DailyTotal> data;@override State<WeeklyBarChart> createState()=>_WeeklyBarChartState();}
class _WeeklyBarChartState extends State<WeeklyBarChart> with SingleTickerProviderStateMixin{late AnimationController c;@override void initState(){super.initState();c=AnimationController(vsync:this,duration:const Duration(milliseconds:800))..forward();}@override void didUpdateWidget(covariant WeeklyBarChart old){super.didUpdateWidget(old);if(old.data!=widget.data)c..reset()..forward();}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context){final max=widget.data.fold<int>(0,(m,e)=>m>e.amount?m:e.amount);return Column(children:[SizedBox(height:210,child:AnimatedBuilder(animation:c,builder:(context,_)=>CustomPaint(painter:_Bars(widget.data,max,c.value,Theme.of(context).colorScheme.primary)))),Row(children:widget.data.map((e)=>Expanded(child:Center(child:Text(['M','T','W','T','F','S','S'][e.date.weekday-1])))).toList()),const SizedBox(height:8),Align(alignment:Alignment.centerLeft,child:Text('Peak: '+formatVnd(max),style:Theme.of(context).textTheme.bodySmall))]);}}
class _Bars extends CustomPainter{_Bars(this.data,this.max,this.progress,this.color);final List<DailyTotal> data;final int max;final double progress;final Color color;@override void paint(Canvas canvas,Size size){final slot=size.width/data.length;for(var i=0;i<data.length;i++){final double h=max==0?0:(size.height-20)*data[i].amount/max*progress;final w=slot*.55;canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(i*slot+(slot-w)/2,size.height-h,w,h),const Radius.circular(10)),Paint()..color=color);}}@override bool shouldRepaint(covariant _Bars old)=>old.progress!=progress||old.data!=data;}
